CREATE OR REPLACE FUNCTION "public"."admin_ban_user"("p_user_id" "uuid", "p_reason" "text") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_banned_at timestamptz;
begin
  if p_reason is null or length(p_reason) = 0 then
    raise exception 'INVALID_INPUT' using detail = 'reason is required';
  end if;

  -- Keep the first ban time when banning twice.
  update public.profiles
     set banned_at = coalesce(banned_at, now())
   where id = p_user_id
  returning banned_at into v_banned_at;
  if not found then
    raise exception 'PROFILE_NOT_FOUND';
  end if;

  update public.partner_links
     set revoked_at = now(), link_code = null, code_expires_at = null
   where user_id = p_user_id
     and revoked_at is null;

  insert into public.admin_audit_log (action, user_id, reason) values ('ban_user', p_user_id, p_reason);
  return v_banned_at;
end;
$$;


ALTER FUNCTION "public"."admin_ban_user"("p_user_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_batch_adjust_credits"("p_actor" "uuid", "p_user_ids" "uuid"[], "p_pool" "text", "p_amount" integer, "p_reason" "text", "p_batch_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_reason text := btrim(coalesce(p_reason, ''));
  v_ids uuid[];
  v_bad uuid[];
  v_id uuid;
  v_applied integer := 0;
begin
  if p_actor is null or not exists (select 1 from public.profiles where id = p_actor and role = 'admin') then
    raise exception 'NOT_ADMIN';
  end if;
  if p_pool is null or p_pool not in ('free', 'paid') then
    raise exception 'INVALID_INPUT' using detail = 'pool must be free or paid';
  end if;
  if p_amount is null or p_amount = 0 or abs(p_amount) > 100000 then
    raise exception 'INVALID_INPUT' using detail = 'amount must be a non-zero integer up to 100000';
  end if;
  if length(v_reason) = 0 or length(v_reason) > 500 then
    raise exception 'INVALID_INPUT' using detail = 'reason is required, at most 500 characters';
  end if;
  if p_batch_key is null or length(p_batch_key) = 0 or length(p_batch_key) > 64 then
    raise exception 'INVALID_INPUT' using detail = 'batch key is required';
  end if;
  if p_user_ids is null or cardinality(p_user_ids) = 0 or cardinality(p_user_ids) > 50
     or array_position(p_user_ids, null) is not null then
    raise exception 'INVALID_INPUT' using detail = 'between 1 and 50 users';
  end if;

  select array_agg(distinct i order by i) into v_ids from unnest(p_user_ids) as i;
  if cardinality(v_ids) <> cardinality(p_user_ids) then
    raise exception 'INVALID_INPUT' using detail = 'a user is listed twice';
  end if;

  perform 1 from public.profiles where id = any(v_ids) order by id for update;

  select array_agg(i order by i) into v_bad
    from unnest(v_ids) as i
   where not exists (select 1 from public.profiles p where p.id = i);
  if v_bad is not null then
    raise exception 'PROFILE_NOT_FOUND' using detail = array_to_string(v_bad, ',');
  end if;

  if exists (
    select 1
      from unnest(v_ids) as i
      join public.credit_ledger l on l.idempotency_key = 'admin_batch:' || p_batch_key || ':' || i::text
     where l.user_id <> i or l.kind <> 'admin_adjust' or l.pool <> p_pool or l.delta <> p_amount
  ) then
    raise exception 'IDEMPOTENCY_CONFLICT';
  end if;

  -- Users this batch already adjusted are skipped, so a resubmit never trips over the balance
  -- its own first run produced.
  select array_agg(p.id order by p.id) into v_bad
    from public.profiles p
   where p.id = any(v_ids)
     and not exists (
       select 1 from public.credit_ledger l
        where l.idempotency_key = 'admin_batch:' || p_batch_key || ':' || p.id::text
     )
     and (case when p_pool = 'paid' then p.credits else p.free_credits end) + p_amount < 0;
  if v_bad is not null then
    raise exception 'CREDITS_INSUFFICIENT' using detail = array_to_string(v_bad, ',');
  end if;

  foreach v_id in array v_ids loop
    if (public._apply_credit_change(
          v_id, p_pool, 'admin_adjust', p_amount, v_reason || ' · 操作人 ' || p_actor::text,
          'admin_batch:' || p_batch_key || ':' || v_id::text
        )).applied then
      v_applied := v_applied + 1;
    end if;
  end loop;

  return jsonb_build_object('applied', v_applied, 'repeated', cardinality(v_ids) - v_applied);
end;
$$;


ALTER FUNCTION "public"."admin_batch_adjust_credits"("p_actor" "uuid", "p_user_ids" "uuid"[], "p_pool" "text", "p_amount" integer, "p_reason" "text", "p_batch_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_batch_set_banned"("p_actor" "uuid", "p_user_ids" "uuid"[], "p_banned" boolean, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_reason text := btrim(coalesce(p_reason, ''));
  v_ids uuid[];
  v_bad uuid[];
  v_id uuid;
  v_changed integer := 0;
begin
  if p_actor is null or not exists (select 1 from public.profiles where id = p_actor and role = 'admin') then
    raise exception 'NOT_ADMIN';
  end if;
  if p_banned is null then
    raise exception 'INVALID_INPUT' using detail = 'banned must be true or false';
  end if;
  if length(v_reason) = 0 or length(v_reason) > 500 then
    raise exception 'INVALID_INPUT' using detail = 'reason is required, at most 500 characters';
  end if;
  if p_user_ids is null or cardinality(p_user_ids) = 0 or cardinality(p_user_ids) > 50
     or array_position(p_user_ids, null) is not null then
    raise exception 'INVALID_INPUT' using detail = 'between 1 and 50 users';
  end if;

  select array_agg(distinct i order by i) into v_ids from unnest(p_user_ids) as i;
  if cardinality(v_ids) <> cardinality(p_user_ids) then
    raise exception 'INVALID_INPUT' using detail = 'a user is listed twice';
  end if;

  perform 1 from public.profiles where id = any(v_ids) order by id for update;

  select array_agg(i order by i) into v_bad
    from unnest(v_ids) as i
   where not exists (select 1 from public.profiles p where p.id = i);
  if v_bad is not null then
    raise exception 'PROFILE_NOT_FOUND' using detail = array_to_string(v_bad, ',');
  end if;

  if p_banned then
    select array_agg(p.id order by p.id) into v_bad
      from public.profiles p
     where p.id = any(v_ids) and (p.role = 'admin' or p.id = p_actor);
    if v_bad is not null then
      raise exception 'PROTECTED_USER' using detail = array_to_string(v_bad, ',');
    end if;
  end if;

  for v_id in
    select p.id from public.profiles p
     where p.id = any(v_ids) and (p.banned_at is null) = p_banned
     order by p.id
  loop
    if p_banned then
      perform public.admin_ban_user(v_id, v_reason || ' · 操作人 ' || p_actor::text);
    else
      perform public.admin_unban_user(v_id, v_reason || ' · 操作人 ' || p_actor::text);
    end if;
    v_changed := v_changed + 1;
  end loop;

  return jsonb_build_object('changed', v_changed, 'unchanged', cardinality(v_ids) - v_changed);
end;
$$;


ALTER FUNCTION "public"."admin_batch_set_banned"("p_actor" "uuid", "p_user_ids" "uuid"[], "p_banned" boolean, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_bulk_edit_templates"("p_ids" "text"[], "p_patch" "jsonb", "p_floor" "jsonb", "p_actor" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $_$
declare
  v_ids text[] := array(select distinct u.id from unnest(coalesce(p_ids, '{}')) as u(id));
  v_patch jsonb := coalesce(p_patch, '{}');
  v_cost jsonb := coalesce(p_patch -> 'credits_cost', '{}');
  v_visible text[];
  v_category text := p_patch ->> 'category_key';
  v_failures jsonb;
  v_changed integer;
begin
  if p_actor is null then
    raise exception 'INVALID_INPUT' using detail = 'actor is required';
  end if;
  if not exists (select 1 from public.profiles p where p.id = p_actor and p.role = 'admin') then
    raise exception 'NOT_ADMIN';
  end if;
  if cardinality(v_ids) = 0 or cardinality(v_ids) > 200 then
    raise exception 'INVALID_INPUT' using detail = 'between 1 and 200 templates';
  end if;
  if jsonb_typeof(v_patch) <> 'object' or v_patch = '{}' or v_patch - 'credits_cost' - 'visible_in' - 'quality' - 'category_key' <> '{}' then
    raise exception 'INVALID_INPUT' using detail = 'patch must name credits_cost, visible_in, quality or category_key';
  end if;
  if v_patch ? 'quality' and (v_patch ->> 'quality') is distinct from 'high' and (v_patch ->> 'quality') is distinct from 'medium' then
    raise exception 'INVALID_INPUT' using detail = 'quality must be high or medium';
  end if;
  if jsonb_typeof(v_cost) <> 'object' then
    raise exception 'INVALID_INPUT' using detail = 'credits_cost must be an object';
  end if;
  if exists (
    select 1 from jsonb_each(v_cost) as e(key, value)
    where e.key not in ('1k', '2k', '3k') or jsonb_typeof(e.value) <> 'number' or e.value::text !~ '^[1-9][0-9]{0,2}$'
  ) then
    raise exception 'INVALID_INPUT' using detail = 'credits_cost tiers must be whole numbers 1..999';
  end if;
  if v_patch ? 'visible_in' then
    if jsonb_typeof(v_patch -> 'visible_in') <> 'array' then
      raise exception 'INVALID_INPUT' using detail = 'visible_in must be an array';
    end if;
    v_visible := array(select distinct x from jsonb_array_elements_text(v_patch -> 'visible_in') as v(x) order by x desc);
    if cardinality(v_visible) = 0 or not (v_visible <@ array['web', 'partner']) then
      raise exception 'INVALID_INPUT' using detail = 'visible_in must be web, partner or both';
    end if;
  end if;
  if v_patch ? 'category_key' then
    -- Held until commit, so the category cannot be deleted under this write.
    perform 1 from public.template_categories c where c.key = v_category and not c.is_system for share;
    if not found then
      raise exception 'CATEGORY_NOT_FOUND' using detail = 'category_key must name a category that is not a system one';
    end if;
  end if;
  if p_floor is null or exists (
    select 1 from unnest(array['high', 'medium']) as q(quality), unnest(array['1k', '2k', '3k']) as r(res)
    where jsonb_typeof(p_floor -> q.quality -> r.res) is distinct from 'number'
  ) then
    raise exception 'INVALID_INPUT' using detail = 'floor table is incomplete';
  end if;

  -- The rows are checked and written under one lock, so no other save slips in between.
  perform 1 from public.templates t where t.id = any (v_ids) for update;

  with planned as (
    select a.id, t.id is not null as found, coalesce(t.name, a.id) as name, t.is_active,
           t.description, t.cover_before_url, t.cover_after_url, t.visible_in as old_visible,
           coalesce(v_patch ->> 'quality', t.quality) as quality,
           t.credits_cost || v_cost as credits_cost,
           coalesce(v_visible, t.visible_in) as visible_in,
           a.id in ('edit', 'freeform') or coalesce(c.is_system, false) as is_builtin
    from unnest(v_ids) as a(id)
    left join public.templates t on t.id = a.id
    left join public.template_categories c on c.key = t.category_key
  ),
  failures as (
    select jsonb_build_object('id', p.id, 'name', p.name, 'reason', case when p.found then 'system' else 'not_found' end) as failure
    from planned p
    where not p.found or p.is_builtin
    union all
    select jsonb_build_object(
      'id', p.id, 'name', p.name, 'reason', 'below_floor', 'resolution', r.res,
      'floor', (p_floor -> p.quality ->> r.res)::integer, 'given', (p.credits_cost ->> r.res)::integer
    )
    from planned p
    cross join unnest(array['1k', '2k', '3k']) as r(res)
    where p.found and not p.is_builtin and (p.credits_cost ->> r.res)::integer < (p_floor -> p.quality ->> r.res)::integer
    union all
    select jsonb_build_object('id', p.id, 'name', p.name, 'reason', 'web_incomplete')
    from planned p
    where p.found and not p.is_builtin and p.is_active
      and 'web' = any (p.visible_in) and not ('web' = any (p.old_visible))
      and (nullif(btrim(p.description), '') is null or nullif(btrim(p.cover_before_url), '') is null
           or nullif(btrim(p.cover_after_url), '') is null)
  )
  select coalesce(jsonb_agg(f.failure), '[]'::jsonb) into v_failures from failures f;

  if jsonb_array_length(v_failures) > 0 then
    return jsonb_build_object('failures', v_failures);
  end if;

  update public.templates t
  set quality = coalesce(v_patch ->> 'quality', t.quality),
      credits_cost = t.credits_cost || v_cost,
      visible_in = coalesce(v_visible, t.visible_in),
      -- templates.category (the English name) follows through T75's trigger.
      category_key = coalesce(v_category, t.category_key),
      featured_rank = case when v_visible is not null and not ('web' = any (v_visible)) then null else t.featured_rank end
  where t.id = any (v_ids);
  get diagnostics v_changed = row_count;

  return jsonb_build_object('failures', '[]'::jsonb, 'changed', v_changed);
end;
$_$;


ALTER FUNCTION "public"."admin_bulk_edit_templates"("p_ids" "text"[], "p_patch" "jsonb", "p_floor" "jsonb", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_clawback_payment"("p_payment_id" bigint, "p_actor" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_payment public.payments;
  v_granted integer;
  v_balance integer;
  v_take integer;
  v_key text;
begin
  if p_actor is null or not exists (select 1 from public.profiles where id = p_actor and role = 'admin') then
    raise exception 'NOT_ADMIN';
  end if;

  select * into v_payment from public.payments where id = p_payment_id for update;
  if not found then
    raise exception 'PAYMENT_NOT_FOUND';
  end if;

  v_granted := public._payment_granted_credits(v_payment);
  select credits into v_balance from public.profiles where id = v_payment.user_id for update;
  v_take := greatest(0, least(coalesce(v_balance, 0), v_granted - v_payment.credits_clawed_back - v_payment.clawback_shortfall));

  if v_take > 0 then
    v_key := 'clawback:' || p_payment_id || ':admin:' || (v_payment.credits_clawed_back + v_payment.clawback_shortfall);
    if (public._apply_credit_change(v_payment.user_id, 'paid', 'clawback', -v_take,
          '后台扣回付款 #' || p_payment_id || ' 的剩余积分 · 操作人 ' || p_actor::text, v_key)).applied then
      update public.credit_ledger set payment_id = p_payment_id where idempotency_key = v_key;
      update public.payments set credits_clawed_back = credits_clawed_back + v_take
       where id = p_payment_id
      returning * into v_payment;
      insert into public.admin_audit_log (action, user_id, reason, target_id)
      values ('clawback_payment', v_payment.user_id, '扣回 ' || v_take || ' 积分 · 操作人 ' || p_actor::text, p_payment_id::text);
    else
      v_take := 0;
    end if;
  end if;

  return jsonb_build_object(
    'taken', v_take,
    'credits_clawed_back', v_payment.credits_clawed_back,
    'clawback_shortfall', v_payment.clawback_shortfall
  );
end;
$$;


ALTER FUNCTION "public"."admin_clawback_payment"("p_payment_id" bigint, "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_daily_costs"("p_days" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_today timestamptz;
  v_start timestamptz;
begin
  if p_days is null or p_days < 1 or p_days > 90 then
    raise exception 'INVALID_INPUT' using detail = 'p_days must be between 1 and 90';
  end if;

  v_today := date_trunc('day', now() at time zone 'UTC') at time zone 'UTC';
  v_start := v_today - make_interval(days => p_days - 1);

  return (
    with jobs as (
      select date_trunc('day', g.created_at at time zone 'UTC') as day, g.status, g.provider_usage, g.cost_usd
        from public.generation_jobs g
       where g.created_at >= v_start
    ),
    per_day as (
      select j.day,
             coalesce(sum(j.cost_usd), 0) as cost_usd,
             count(*) filter (where j.cost_usd is not null) as costed,
             count(*) filter (where j.cost_usd is null and j.provider_usage is not null) as uncosted,
             count(*) filter (where j.cost_usd is null and j.provider_usage is null and j.status <> 'running') as no_usage
        from jobs j
       group by j.day
    )
    select coalesce(jsonb_agg(jsonb_build_object(
             'day', to_char(d.day, 'YYYY-MM-DD'),
             'cost_usd', coalesce(p.cost_usd, 0),
             'costed', coalesce(p.costed, 0),
             'uncosted', coalesce(p.uncosted, 0),
             'no_usage', coalesce(p.no_usage, 0)
           ) order by d.day), '[]'::jsonb)
      from generate_series(v_start at time zone 'UTC', v_today at time zone 'UTC', interval '1 day') as d(day)
      left join per_day p on p.day = d.day
  );
end;
$$;


ALTER FUNCTION "public"."admin_daily_costs"("p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_dashboard_stats"("p_days" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_tz constant text := 'Asia/Shanghai';
  v_today timestamptz;
  v_start timestamptz;
  v_result jsonb;
begin
  if p_days is null or p_days < 7 or p_days > 90 then
    raise exception 'INVALID_INPUT' using detail = 'p_days must be between 7 and 90';
  end if;

  v_today := date_trunc('day', now() at time zone v_tz) at time zone v_tz;
  v_start := v_today - make_interval(days => p_days - 1);

  with windows(key, since) as (
    values ('today', v_today), ('7d', v_today - interval '6 days'), ('period', v_start)
  ),
  jobs as (
    select g.created_at,
           g.status,
           -- generation_jobs.provider is '<source>/<model>'; older rows hold a bare name.
           case when position('/' in g.provider) > 0
                then substr(g.provider, position('/' in g.provider) + 1)
                else coalesce(g.provider, 'unknown') end as model,
           coalesce(g.inputs ->> 'resolution', '1k') as resolution,
           g.cost_usd,
           g.provider_usage is not null and g.cost_usd is null as uncosted,
           g.status = 'succeeded' and g.provider_usage is null and g.cost_usd is null as legacy
      from public.generation_jobs g
     where g.created_at >= v_start
  ),
  -- Net credits spent on generation: reserves minus refunds, per pool.
  spend as (
    select l.created_at, l.pool, -l.delta as used
      from public.credit_ledger l
     where l.created_at >= v_start and l.kind in ('reserve', 'refund')
  ),
  -- A paying user is new on the day of their first purchase ever.
  first_purchases as (
    select l.user_id, min(l.created_at) as first_at
      from public.credit_ledger l
     where l.created_at >= v_start
       and l.kind = 'purchase'
       and not exists (
         select 1 from public.credit_ledger e
          where e.user_id = l.user_id and e.kind = 'purchase' and e.created_at < v_start
       )
     group by l.user_id
  ),
  window_stats as (
    select jsonb_agg(jsonb_build_object(
             'key', w.key,
             'since', w.since,
             'signups', (select count(*) from public.profiles p where p.created_at >= w.since),
             'jobs', (select count(*) from jobs j where j.created_at >= w.since),
             'succeeded', (select count(*) from jobs j where j.created_at >= w.since and j.status = 'succeeded'),
             'failed', (select count(*) from jobs j where j.created_at >= w.since and j.status = 'failed'),
             'free_credits_used', (select coalesce(sum(s.used), 0) from spend s where s.created_at >= w.since and s.pool = 'free'),
             'paid_credits_used', (select coalesce(sum(s.used), 0) from spend s where s.created_at >= w.since and s.pool = 'paid'),
             'new_paying_users', (select count(*) from first_purchases f where f.first_at >= w.since),
             'cost_usd', (select coalesce(sum(j.cost_usd), 0) from jobs j where j.created_at >= w.since),
             'uncosted', (select count(*) from jobs j where j.created_at >= w.since and j.uncosted),
             'legacy', (select coalesce(jsonb_object_agg(r.resolution, r.n), '{}'::jsonb)
                          from (select j.resolution, count(*) as n from jobs j
                                 where j.created_at >= w.since and j.legacy group by j.resolution) r)
           ) order by w.since desc) as value
      from windows w
  ),
  trend as (
    select jsonb_agg(jsonb_build_object(
             'day', to_char(d.day at time zone v_tz, 'YYYY-MM-DD'),
             'jobs', (select count(*) from jobs j where j.created_at >= d.day and j.created_at < d.day + interval '1 day'),
             'succeeded', (select count(*) from jobs j
                            where j.created_at >= d.day and j.created_at < d.day + interval '1 day' and j.status = 'succeeded'),
             'cost_usd', (select coalesce(sum(j.cost_usd), 0) from jobs j
                           where j.created_at >= d.day and j.created_at < d.day + interval '1 day'),
             'legacy', (select coalesce(jsonb_object_agg(r.resolution, r.n), '{}'::jsonb)
                          from (select j.resolution, count(*) as n from jobs j
                                 where j.created_at >= d.day and j.created_at < d.day + interval '1 day' and j.legacy
                                 group by j.resolution) r)
           ) order by d.day) as value
      from generate_series(v_start, v_today, interval '1 day') as d(day)
  ),
  by_model as (
    select jsonb_agg(jsonb_build_object(
             'model', m.model, 'resolution', m.resolution, 'jobs', m.jobs, 'succeeded', m.succeeded,
             'cost_usd', m.cost_usd, 'uncosted', m.uncosted, 'legacy', m.legacy
           ) order by m.jobs desc, m.model, m.resolution) as value
      from (
        select j.model, j.resolution, count(*) as jobs, count(*) filter (where j.status = 'succeeded') as succeeded,
               coalesce(sum(j.cost_usd), 0) as cost_usd,
               count(*) filter (where j.uncosted) as uncosted,
               count(*) filter (where j.legacy) as legacy
          from jobs j
         group by j.model, j.resolution
      ) m
  )
  select jsonb_build_object(
           'timezone', v_tz,
           'days', p_days,
           'generated_at', now(),
           'windows', (select value from window_stats),
           'trend', coalesce((select value from trend), '[]'::jsonb),
           'by_model', coalesce((select value from by_model), '[]'::jsonb)
         )
    into v_result;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."admin_dashboard_stats"("p_days" integer) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."support_tickets" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "type" "text" NOT NULL,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "payment_id" bigint,
    "job_id" "uuid",
    "refund_decision" "text",
    "refund_amount_cents" integer,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_message_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "user_seen_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "closed_at" timestamp with time zone,
    CONSTRAINT "support_tickets_closed" CHECK ((("status" = 'closed'::"text") = ("closed_at" IS NOT NULL))),
    CONSTRAINT "support_tickets_decision_amount" CHECK ((("refund_decision" = 'approved'::"text") = ("refund_amount_cents" IS NOT NULL))),
    CONSTRAINT "support_tickets_decision_type" CHECK ((("refund_decision" IS NULL) OR ("type" = 'refund'::"text"))),
    CONSTRAINT "support_tickets_job_type" CHECK ((("job_id" IS NULL) OR ("type" = 'image_issue'::"text"))),
    CONSTRAINT "support_tickets_payment_type" CHECK ((("payment_id" IS NULL) OR ("type" = ANY (ARRAY['billing'::"text", 'refund'::"text"])))),
    CONSTRAINT "support_tickets_refund_amount_cents_check" CHECK (("refund_amount_cents" > 0)),
    CONSTRAINT "support_tickets_refund_decision_check" CHECK (("refund_decision" = ANY (ARRAY['approved'::"text", 'rejected'::"text"]))),
    CONSTRAINT "support_tickets_refund_payment" CHECK ((("type" <> 'refund'::"text") OR ("payment_id" IS NOT NULL))),
    CONSTRAINT "support_tickets_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'replied'::"text", 'closed'::"text"]))),
    CONSTRAINT "support_tickets_type_check" CHECK (("type" = ANY (ARRAY['feedback'::"text", 'image_issue'::"text", 'billing'::"text", 'refund'::"text", 'account'::"text", 'other'::"text"])))
);


ALTER TABLE "public"."support_tickets" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_decide_refund"("p_ticket_id" "uuid", "p_decision" "text", "p_amount_cents" integer, "p_body" "text") RETURNS "public"."support_tickets"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_ticket public.support_tickets;
  v_left integer;
  v_body text := btrim(coalesce(p_body, ''));
begin
  if p_decision is null or p_decision not in ('approved', 'rejected') then
    raise exception 'INVALID_INPUT' using detail = 'decision must be approved or rejected';
  end if;
  if char_length(v_body) not between 1 and 2000 then
    raise exception 'INVALID_INPUT' using detail = 'a decision needs a reply of 1 to 2000 characters';
  end if;

  select * into v_ticket from public.support_tickets t where t.id = p_ticket_id for update;
  if not found then
    raise exception 'TICKET_NOT_FOUND';
  end if;
  if v_ticket.type <> 'refund' then
    raise exception 'INVALID_INPUT' using detail = 'not a refund ticket';
  end if;

  select p.amount_total - p.amount_refunded into v_left from public.payments p where p.id = v_ticket.payment_id;
  if p_decision = 'approved' and (p_amount_cents is null or p_amount_cents not between 1 and v_left) then
    raise exception 'INVALID_INPUT' using detail = 'amount must be between 1 and the unrefunded total';
  end if;
  if p_decision = 'rejected' and p_amount_cents is not null then
    raise exception 'INVALID_INPUT' using detail = 'a rejection takes no amount';
  end if;

  update public.support_tickets
     set refund_decision = p_decision,
         refund_amount_cents = p_amount_cents,
         status = 'replied',
         closed_at = null,
         last_message_at = now()
   where id = p_ticket_id
  returning * into v_ticket;

  insert into public.support_ticket_messages (ticket_id, author, body) values (p_ticket_id, 'admin', v_body);

  insert into public.admin_audit_log (action, user_id, target_id, reason)
  values (
    'decide_refund',
    v_ticket.user_id,
    p_ticket_id::text,
    format('退款工单：%s%s', p_decision, case when p_amount_cents is null then '' else ' ' || p_amount_cents end)
  );
  return v_ticket;
end;
$$;


ALTER FUNCTION "public"."admin_decide_refund"("p_ticket_id" "uuid", "p_decision" "text", "p_amount_cents" integer, "p_body" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_delete_provider"("p_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_active boolean;
begin
  -- Row lock: a concurrent switch to this row waits for the delete, or the delete sees it active.
  select is_active into v_active from public.ai_providers where id = p_id for update;
  if not found then
    raise exception 'PROVIDER_NOT_FOUND';
  end if;
  -- The module would silently fall back (env, or none for decision): switch first.
  if v_active then
    raise exception 'PROVIDER_ACTIVE' using errcode = '55000';
  end if;

  delete from public.ai_providers where id = p_id;
  delete from vault.secrets where name = 'shotviva.provider.' || p_id::text;
end;
$$;


ALTER FUNCTION "public"."admin_delete_provider"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_delete_template_category"("p_key" "text", "p_move_to" "text", "p_actor" "uuid") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_moved integer;
begin
  if p_actor is null or not exists (select 1 from public.profiles p where p.id = p_actor and p.role = 'admin') then
    raise exception 'NOT_ADMIN';
  end if;
  perform 1 from public.template_categories for update;
  if not exists (select 1 from public.template_categories c where c.key = p_key) then
    raise exception 'CATEGORY_NOT_FOUND';
  end if;
  if exists (select 1 from public.template_categories c where c.key = p_key and c.is_system) then
    raise exception 'CATEGORY_SYSTEM';
  end if;
  if (select count(*) from public.template_categories c where not c.is_system) <= 1 then
    raise exception 'CATEGORY_LAST';
  end if;

  if exists (select 1 from public.templates t where t.category_key = p_key) then
    if p_move_to is null then
      raise exception 'CATEGORY_MOVE_REQUIRED';
    end if;
    if p_move_to = p_key or not exists (select 1 from public.template_categories c where c.key = p_move_to and not c.is_system) then
      raise exception 'INVALID_INPUT' using detail = 'move_to must be another existing, non-system category';
    end if;
    update public.templates set category_key = p_move_to where category_key = p_key;
    get diagnostics v_moved = row_count;
  else
    v_moved := 0;
  end if;

  delete from public.template_categories where key = p_key;
  return v_moved;
end;
$$;


ALTER FUNCTION "public"."admin_delete_template_category"("p_key" "text", "p_move_to" "text", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_get_dispute"("p_dispute_id" "text") RETURNS TABLE("stripe_dispute_id" "text", "stripe_charge_id" "text", "payment_id" bigint, "user_id" "uuid", "email" "text", "product_id" "text", "amount" integer, "currency" "text", "reason" "text", "responder" "text", "due_by" timestamp with time zone, "auto_banned_at" timestamp with time zone, "evidence_drafted_at" timestamp with time zone, "submitted_at" timestamp with time zone, "reminded_at" timestamp with time zone, "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select d.stripe_dispute_id, d.stripe_charge_id, d.payment_id, d.user_id, coalesce(nullif(u.email::text, ''), nullif(u.phone::text, '')),
         p.product_id, d.amount, d.currency, d.reason, d.responder, d.due_by,
         d.auto_banned_at, d.evidence_drafted_at, d.submitted_at, d.reminded_at, d.created_at
    from public.payment_disputes d
    left join auth.users u on u.id = d.user_id
    left join public.payments p on p.id = d.payment_id
   where d.stripe_dispute_id = p_dispute_id;
$$;


