CREATE OR REPLACE FUNCTION "public"."admin_list_tickets"("p_status" "text", "p_type" "text", "p_cursor_at" timestamp with time zone, "p_cursor_id" "uuid", "p_limit" integer) RETURNS TABLE("id" "uuid", "user_id" "uuid", "email" "text", "type" "text", "status" "text", "payment_id" bigint, "job_id" "uuid", "refund_decision" "text", "created_at" timestamp with time zone, "last_message_at" timestamp with time zone, "preview" "text", "tier" "text", "due_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_status is not null and p_status not in ('open', 'replied', 'closed') then
    raise exception 'INVALID_INPUT' using detail = 'unknown status';
  end if;
  if p_type is not null and p_type not in ('feedback', 'image_issue', 'billing', 'refund', 'account', 'other') then
    raise exception 'INVALID_INPUT' using detail = 'unknown ticket type';
  end if;
  if p_limit is null or p_limit not between 1 and 101 then
    raise exception 'INVALID_INPUT' using detail = 'p_limit must be between 1 and 101';
  end if;

  if p_status = 'open' then
    return query
      with open_rows as (
        select t.id, t.user_id, t.type, t.status, t.payment_id, t.job_id, t.refund_decision,
               t.created_at, t.last_message_at, d.tier,
               coalesce(d.last_user_at, t.created_at) + make_interval(hours => public.support_reply_hours(d.tier)) as due_at
          from public.support_tickets t
          cross join lateral (
            select public.current_tier(t.user_id) as tier,
                   (select max(m.created_at) from public.support_ticket_messages m
                     where m.ticket_id = t.id and m.author = 'user') as last_user_at
          ) d
         where t.status = 'open'
           and (p_type is null or t.type = p_type)
      )
      select r.id, r.user_id, u.email::text, r.type, r.status, r.payment_id, r.job_id, r.refund_decision,
             r.created_at, r.last_message_at, f.preview, r.tier, r.due_at
        from open_rows r
        left join auth.users u on u.id = r.user_id
        left join lateral (
          select left(m.body, 140) as preview from public.support_ticket_messages m
           where m.ticket_id = r.id order by m.created_at limit 1
        ) f on true
       where p_cursor_at is null or (r.due_at, r.id) > (p_cursor_at, p_cursor_id)
       order by r.due_at, r.id
       limit p_limit;
  else
    return query
      select t.id, t.user_id, u.email::text, t.type, t.status, t.payment_id, t.job_id, t.refund_decision,
             t.created_at, t.last_message_at, f.preview, d.tier,
             coalesce(d.last_user_at, t.created_at) + make_interval(hours => public.support_reply_hours(d.tier))
        from public.support_tickets t
        left join auth.users u on u.id = t.user_id
        cross join lateral (
          select public.current_tier(t.user_id) as tier,
                 (select max(m.created_at) from public.support_ticket_messages m
                   where m.ticket_id = t.id and m.author = 'user') as last_user_at
        ) d
        left join lateral (
          select left(m.body, 140) as preview from public.support_ticket_messages m
           where m.ticket_id = t.id order by m.created_at limit 1
        ) f on true
       where (p_status is null or t.status = p_status)
         and (p_type is null or t.type = p_type)
         and (p_cursor_at is null or (t.last_message_at, t.id) < (p_cursor_at, p_cursor_id))
       order by t.last_message_at desc, t.id desc
       limit p_limit;
  end if;
end;
$$;


ALTER FUNCTION "public"."admin_list_tickets"("p_status" "text", "p_type" "text", "p_cursor_at" timestamp with time zone, "p_cursor_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_users"("p_query" "text" DEFAULT NULL::"text", "p_tier" "text" DEFAULT NULL::"text", "p_provider" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_sort" "text" DEFAULT 'created'::"text", "p_page" integer DEFAULT 1) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  -- A ledger row that names the plan of profile p (current_tier()'s rule).
  c_plan constant text := 'l.user_id = p.id and l.pool = ''paid'' and l.delta > 0 '
                          'and l.product_id is not null and l.product_id not like ''pack_%''';
  v_q text := nullif(btrim(coalesce(p_query, '')), '');
  v_like text;
  v_digits text;
  v_where text := 'true';
  v_from text := 'public.profiles p';
  v_order text := 'p.created_at desc, p.id desc';
  v_total bigint;
  v_ids uuid[];
begin
  if p_tier is not null and p_tier not in ('free', 'starter', 'pro', 'max') then
    raise exception 'INVALID_INPUT' using detail = 'tier must be free, starter, pro or max';
  end if;
  if p_provider is not null and p_provider not in ('email', 'google', 'phone') then
    raise exception 'INVALID_INPUT' using detail = 'provider must be email, google or phone';
  end if;
  if p_status is not null and p_status not in ('active', 'banned') then
    raise exception 'INVALID_INPUT' using detail = 'status must be active or banned';
  end if;
  if p_sort is null or p_sort not in ('created', 'last_job', 'paid_credits') then
    raise exception 'INVALID_INPUT' using detail = 'sort must be created, last_job or paid_credits';
  end if;
  if p_page is null or p_page < 1 or p_page > 10000 then
    raise exception 'INVALID_INPUT' using detail = 'page must be between 1 and 10000';
  end if;
  if length(v_q) > 320 then
    raise exception 'INVALID_INPUT' using detail = 'query is too long';
  end if;

  -- The lookup box's substring rules (admin_search_users, 0442): % and _ match themselves; a
  -- query of digits, spaces, dashes and a leading + with at least 4 digits also matches the phone.
  if v_q is not null then
    v_like := '%' || replace(replace(replace(v_q, '\', '\\'), '%', '\%'), '_', '\_') || '%';
    if v_q ~ '^\+?[0-9][0-9 -]{2,}$' and length(regexp_replace(v_q, '[^0-9]', '', 'g')) >= 4 then
      v_digits := regexp_replace(v_q, '[^0-9]', '', 'g');
    end if;
  end if;

  -- Parameters: $1 email pattern, $2 phone digits, $3 sign-up method, $4 from, $5 to, $6 tier,
  -- $7 offset. The method is the one the account signed up with; linking Google later does not
  -- change it.
  if v_q is not null or p_provider is not null then
    v_where := v_where || ' and exists (select 1 from auth.users u where u.id = p.id'
      || case when v_q is null then ''
              when v_digits is null then ' and u.email ilike $1'
              else ' and (u.email ilike $1 or u.phone like ''%'' || $2 || ''%'')' end
      || case when p_provider is null then '' else ' and u.raw_app_meta_data ->> ''provider'' = $3' end
      || ')';
  end if;
  if p_status = 'banned' then
    v_where := v_where || ' and p.banned_at is not null';
  elsif p_status = 'active' then
    v_where := v_where || ' and p.banned_at is null';
  end if;
  if p_from is not null then
    v_where := v_where || ' and p.created_at >= $4';
  end if;
  if p_to is not null then
    v_where := v_where || ' and p.created_at < $5';
  end if;
  if p_tier = 'free' then
    v_where := v_where || ' and (p.paid_until is null or p.paid_until <= now() '
      || 'or not exists (select 1 from public.credit_ledger l where ' || c_plan || '))';
  elsif p_tier is not null then
    v_where := v_where || ' and p.paid_until > now() and split_part((select l.product_id '
      || 'from public.credit_ledger l where ' || c_plan
      || ' order by l.created_at desc, l.id desc limit 1), ''_'', 1) = $6';
  end if;

  execute 'select count(*) from public.profiles p where ' || v_where
    into v_total
    using v_like, v_digits, p_provider, p_from, p_to, p_tier;

  if p_sort = 'last_job' then
    v_from := v_from || ' left join lateral (select g.created_at from public.generation_jobs g '
      || 'where g.user_id = p.id order by g.created_at desc limit 1) j on true';
    v_order := 'j.created_at desc nulls last, p.created_at desc, p.id desc';
  elsif p_sort = 'paid_credits' then
    v_order := 'p.credits desc, p.created_at desc, p.id desc';
  end if;

  -- ARRAY(subquery) keeps the subquery's order.
  execute 'select array(select p.id from ' || v_from || ' where ' || v_where
      || ' order by ' || v_order || ' limit 50 offset $7)'
    into v_ids
    using v_like, v_digits, p_provider, p_from, p_to, p_tier, (p_page - 1) * 50;

  -- The 50 rows of the page, each joined by primary key.
  return jsonb_build_object(
    'total', v_total,
    'rows', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', p.id,
               'email', u.email::text,
               'phone', nullif(u.phone, '')::text,
               'created_at', p.created_at,
               'provider', u.raw_app_meta_data ->> 'provider',
               'role', p.role,
               'credits', p.credits,
               'free_credits', p.free_credits,
               'paid_until', p.paid_until,
               'tier', coalesce(split_part(plan.product_id, '_', 1), 'free'),
               'product_id', plan.product_id,
               'last_generation_at', j.created_at,
               'banned_at', p.banned_at
             ) order by ids.n)
        from unnest(v_ids) with ordinality as ids(id, n)
        join public.profiles p on p.id = ids.id
        join auth.users u on u.id = p.id
        left join lateral (
          select l.product_id
            from public.credit_ledger l
           where p.paid_until > now()
             and l.user_id = p.id and l.pool = 'paid' and l.delta > 0
             and l.product_id is not null and l.product_id not like 'pack_%'
           order by l.created_at desc, l.id desc
           limit 1
        ) plan on true
        left join lateral (
          select g.created_at
            from public.generation_jobs g
           where g.user_id = p.id
           order by g.created_at desc
           limit 1
        ) j on true
    ), '[]'::jsonb)
  );
end;
$_$;


ALTER FUNCTION "public"."admin_list_users"("p_query" "text", "p_tier" "text", "p_provider" "text", "p_status" "text", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_sort" "text", "p_page" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_log_replay"("p_user_id" "uuid", "p_target_id" "text", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_user_id is null or p_target_id is null or p_target_id !~ '^(cs|sub)_'
     or p_reason is null or length(btrim(p_reason)) = 0 then
    raise exception 'INVALID_INPUT' using detail = 'user, a cs_/sub_ target and a reason are required';
  end if;

  insert into public.admin_audit_log (action, user_id, target_id, reason)
  values ('replay_checkout', p_user_id, p_target_id, p_reason);
end;
$$;


ALTER FUNCTION "public"."admin_log_replay"("p_user_id" "uuid", "p_target_id" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_lookup"("p_query" "text") RETURNS TABLE("kind" "text", "user_id" "uuid", "job_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_q text := btrim(coalesce(p_query, ''));
  v_users uuid[];
begin
  if length(v_q) = 0 or length(v_q) > 320 then
    return;
  end if;

  if v_q ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    return query select 'user'::text, p.id, null::uuid from public.profiles p where p.id = v_q::uuid;
    if found then return; end if;
    return query select 'job'::text, j.user_id, j.id from public.generation_jobs j where j.id = v_q::uuid;
    return;
  end if;

  if v_q like 'cs\_%' then
    return query select 'checkout'::text, pay.user_id, null::uuid from public.payments pay where pay.stripe_session_id = v_q;
    if found then return; end if;
    return query select 'checkout'::text, l.user_id, null::uuid from public.credit_ledger l where l.idempotency_key = 'purchase:' || v_q;
    return;
  end if;

  if v_q like 'in\_%' then
    return query select 'invoice'::text, pay.user_id, null::uuid from public.payments pay where pay.stripe_invoice_id = v_q;
    if found then return; end if;
    return query select 'invoice'::text, l.user_id, null::uuid from public.credit_ledger l where l.idempotency_key = 'renewal:' || v_q;
    return;
  end if;

  if v_q ~ '^(ch|py)_' then
    return query select 'charge'::text, pay.user_id, null::uuid from public.payments pay where pay.stripe_charge_id = v_q;
    return;
  end if;

  if v_q like 'sub\_%' then
    return query select 'subscription'::text, s.user_id, null::uuid from public.subscriptions s where s.stripe_subscription_id = v_q;
    return;
  end if;

  return query select 'waffo'::text, pay.user_id, null::uuid from public.payments pay where pay.waffo_order_id = v_q;
  if found then return; end if;
  return query select 'waffo'::text, l.user_id, null::uuid from public.credit_ledger l where l.idempotency_key = 'purchase:' || v_q;
  if found then return; end if;

  -- The query is a literal substring: % and _ typed by the admin match themselves.
  select array_agg(u.id) into v_users
    from (select au.id from auth.users au
           where au.email ilike '%' || replace(replace(replace(v_q, '\', '\\'), '%', '\%'), '_', '\_') || '%'
           limit 2) u;
  if cardinality(v_users) = 1 then
    return query select 'email'::text, v_users[1], null::uuid;
  end if;
end;
$_$;


ALTER FUNCTION "public"."admin_lookup"("p_query" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_mark_dispute_submitted"("p_dispute_id" "text", "p_actor" "uuid") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.payment_disputes;
begin
  if p_actor is null or not exists (select 1 from public.profiles where id = p_actor and role = 'admin') then
    raise exception 'NOT_ADMIN';
  end if;

  select * into v_row from public.payment_disputes where stripe_dispute_id = p_dispute_id for update;
  if not found then
    raise exception 'DISPUTE_NOT_FOUND';
  end if;
  if v_row.responder <> 'shotviva' then
    raise exception 'DISPUTE_NOT_OURS' using detail = 'Stripe answers Managed Payments disputes';
  end if;
  if v_row.submitted_at is not null then
    raise exception 'DISPUTE_ALREADY_SUBMITTED';
  end if;

  update public.payment_disputes set submitted_at = now(), submitted_by = p_actor
   where stripe_dispute_id = p_dispute_id
  returning * into v_row;

  insert into public.admin_audit_log (action, user_id, reason, target_id)
  values ('submit_dispute', coalesce(v_row.user_id, p_actor), '提交拒付申诉证据 · 操作人 ' || p_actor::text, p_dispute_id);
  return v_row.submitted_at;
end;
$$;


ALTER FUNCTION "public"."admin_mark_dispute_submitted"("p_dispute_id" "text", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_openai_admin_key_status"() RETURNS TABLE("key_last4" "text", "project_id" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
