    AS $$
  select (select right(decrypted_secret, 4) from vault.decrypted_secrets where name = 'shotviva.openai_admin_key'),
         (select decrypted_secret from vault.decrypted_secrets where name = 'shotviva.openai_costs_project');
$$;


ALTER FUNCTION "public"."admin_openai_admin_key_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_reorder_template_categories"("p_keys" "text"[], "p_actor" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_keys text[] := coalesce(p_keys, '{}');
begin
  if p_actor is null or not exists (select 1 from public.profiles p where p.id = p_actor and p.role = 'admin') then
    raise exception 'NOT_ADMIN';
  end if;
  if cardinality(v_keys) <> (select count(distinct k) from unnest(v_keys) as u(k))
     or (select array_agg(k order by k) from unnest(v_keys) as u(k))
        is distinct from (select array_agg(c.key order by c.key) from public.template_categories c where not c.is_system) then
    raise exception 'INVALID_INPUT' using detail = 'the order must list every category once';
  end if;

  update public.template_categories c
  set sort_order = o.position * 10
  from unnest(v_keys) with ordinality as o(key, position)
  where c.key = o.key and c.sort_order <> o.position * 10;
end;
$$;


ALTER FUNCTION "public"."admin_reorder_template_categories"("p_keys" "text"[], "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_reorder_templates"("p_ids" "text"[]) RETURNS "void"
    LANGUAGE "sql"
    SET "search_path" TO ''
    AS $$
  update public.templates t
  set sort_order = o.position * 10
  from unnest(p_ids) with ordinality as o(id, position)
  where t.id = o.id;
$$;


ALTER FUNCTION "public"."admin_reorder_templates"("p_ids" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_reply_ticket"("p_ticket_id" "uuid", "p_body" "text", "p_close" boolean, "p_images" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "public"."support_tickets"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_body text := nullif(btrim(coalesce(p_body, '')), '');
  v_ticket public.support_tickets;
  v_message_id uuid;
begin
  if v_body is null and not coalesce(p_close, false) then
    raise exception 'INVALID_INPUT' using detail = 'a reply needs a message';
  end if;
  if char_length(v_body) > 2000 then
    raise exception 'INVALID_INPUT' using detail = 'body must be at most 2000 characters';
  end if;
  if v_body is null and coalesce(jsonb_array_length(case when jsonb_typeof(p_images) = 'array' then p_images end), 0) > 0 then
    raise exception 'INVALID_INPUT' using detail = 'images need a message';
  end if;

  update public.support_tickets
     set status = case when p_close then 'closed' else 'replied' end,
         closed_at = case when p_close then coalesce(closed_at, now()) end,
         last_message_at = case when v_body is null then last_message_at else now() end
   where id = p_ticket_id
  returning * into v_ticket;
  if not found then
    raise exception 'TICKET_NOT_FOUND';
  end if;

  if v_body is not null then
    insert into public.support_ticket_messages (ticket_id, author, body) values (p_ticket_id, 'admin', v_body)
    returning id into v_message_id;
    perform public.attach_ticket_images(p_ticket_id, v_ticket.user_id, v_message_id, p_images);
  end if;
  return v_ticket;
end;
$$;


ALTER FUNCTION "public"."admin_reply_ticket"("p_ticket_id" "uuid", "p_body" "text", "p_close" boolean, "p_images" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_revenue_stats"("p_days" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_tz constant text := 'Asia/Shanghai';
  v_today timestamptz;
  v_start timestamptz;
  v_result jsonb;
begin
  if p_days is null or p_days < 7 or p_days > 90 then
    raise exception 'INVALID_INPUT' using detail = 'p_days must be between 7 and 90';
  end if;

  v_today := date_trunc('day', now() at time zone v_tz) at time zone v_tz;
  v_start := v_today - make_interval(days => p_days - 1);

  with windows(key, since) as (
    values ('today', v_today), ('7d', v_today - interval '6 days'), ('period', v_start)
  ),
  purchases as (
    select pm.created_at,
           pm.product_id,
           pm.channel,
           case when pm.currency = 'usd'
                then (pm.amount_total - pm.amount_tax - pm.amount_refunded) / 100.0
                else 0 end as amount
      from public.payments pm
     where pm.created_at >= v_start
  )
  select jsonb_build_object(
           'timezone', v_tz,
           'days', p_days,
           'generated_at', now(),
           'windows', (
             select jsonb_agg(jsonb_build_object(
                      'key', w.key,
                      'since', w.since,
                      'purchases', (select count(*) from purchases x where x.created_at >= w.since),
                      'revenue_usd', (select coalesce(sum(x.amount), 0) from purchases x where x.created_at >= w.since)
                    ) order by w.since desc)
               from windows w
           ),
           'by_product', coalesce((
             select jsonb_agg(jsonb_build_object(
                      'product_id', g.product_id, 'channel', g.channel,
                      'purchases', g.purchases, 'revenue_usd', g.revenue
                    ) order by g.revenue desc, g.product_id, g.channel)
               from (
                 select coalesce(x.product_id, 'unknown') as product_id, x.channel,
                        count(*) as purchases, sum(x.amount) as revenue
                   from purchases x
                  group by 1, 2
               ) g
           ), '[]'::jsonb),
           'trend', (
             select jsonb_agg(jsonb_build_object(
                      'day', to_char(d.day at time zone v_tz, 'YYYY-MM-DD'),
                      'revenue_usd', (select coalesce(sum(x.amount), 0) from purchases x
                                       where x.created_at >= d.day and x.created_at < d.day + interval '1 day')
                    ) order by d.day)
               from generate_series(v_start, v_today, interval '1 day') as d(day)
           ),
           'subscriptions', coalesce((
             select jsonb_object_agg(s.status, s.n)
               from (select status, count(*) as n from public.subscriptions group by status) s
           ), '{}'::jsonb)
         )
    into v_result;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."admin_revenue_stats"("p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_review_template_request"("p_request_id" "uuid", "p_status" "text", "p_template_id" "text" DEFAULT NULL::"text") RETURNS "text"[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_current text;
  v_keys text[];
begin
  select r.status, r.image_keys into v_current, v_keys
    from public.template_requests r
   where r.id = p_request_id
     for update;
  if not found then
    raise exception 'REQUEST_NOT_FOUND';
  end if;

  if not (
       (v_current = 'pending' and p_status in ('live', 'rejected'))
    or (v_current = 'live' and p_status in ('rejected', 'shipped'))
  ) then
    raise exception 'REQUEST_TRANSITION_INVALID'
      using detail = v_current || ' -> ' || coalesce(p_status, 'null');
  end if;

  if p_status = 'shipped' then
    perform 1 from public.templates t where t.id = p_template_id;
    if not found then
      raise exception 'TEMPLATE_NOT_FOUND';
    end if;
  end if;

  update public.template_requests
     set status = p_status,
         template_id = case when p_status = 'shipped' then p_template_id end,
         image_keys = case when p_status = 'rejected' then '{}'::text[] else image_keys end,
         reviewed_at = now()
   where id = p_request_id;

  return case when p_status = 'rejected' then v_keys else '{}'::text[] end;
end;
$$;


ALTER FUNCTION "public"."admin_review_template_request"("p_request_id" "uuid", "p_status" "text", "p_template_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_save_template_category"("p_category" "jsonb", "p_is_new" boolean, "p_actor" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_key text := btrim(coalesce(p_category ->> 'key', ''));
  v_name_en text := btrim(coalesce(p_category ->> 'name_en', ''));
  v_name_zh text := btrim(coalesce(p_category ->> 'name_zh', ''));
  v_intro_en text := nullif(btrim(coalesce(p_category ->> 'intro_en', '')), '');
  v_intro_zh text := nullif(btrim(coalesce(p_category ->> 'intro_zh', '')), '');
  v_style text := coalesce(p_category ->> 'card_style', 'pair');
begin
  if p_actor is null or not exists (select 1 from public.profiles p where p.id = p_actor and p.role = 'admin') then
    raise exception 'NOT_ADMIN';
  end if;
  if v_name_en = '' or v_name_zh = '' then
    raise exception 'INVALID_INPUT' using detail = 'both names are required';
  end if;
  if exists (select 1 from public.template_categories c where lower(c.name_en) = lower(v_name_en) and c.key <> v_key) then
    raise exception 'CATEGORY_NAME_EN_TAKEN';
  end if;
  if exists (select 1 from public.template_categories c where c.name_zh = v_name_zh and c.key <> v_key) then
    raise exception 'CATEGORY_NAME_ZH_TAKEN';
  end if;

  if coalesce(p_is_new, false) then
    if exists (select 1 from public.template_categories c where c.key = v_key) then
      raise exception 'CATEGORY_KEY_TAKEN';
    end if;
    insert into public.template_categories (key, name_en, name_zh, intro_en, intro_zh, card_style, sort_order)
    values (
      v_key, v_name_en, v_name_zh, v_intro_en, v_intro_zh, v_style,
      (select coalesce(max(c.sort_order), 0) + 10 from public.template_categories c where not c.is_system)
    );
  else
    if exists (select 1 from public.template_categories c where c.key = v_key and c.is_system) then
      raise exception 'CATEGORY_SYSTEM';
    end if;
    update public.template_categories
    set name_en = v_name_en,
        name_zh = v_name_zh,
        intro_en = v_intro_en,
        intro_zh = v_intro_zh,
        card_style = v_style
    where key = v_key;
    if not found then
      raise exception 'CATEGORY_NOT_FOUND';
    end if;
  end if;
end;
$$;


ALTER FUNCTION "public"."admin_save_template_category"("p_category" "jsonb", "p_is_new" boolean, "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_search_users"("p_query" "text") RETURNS TABLE("id" "uuid", "email" "text", "created_at" timestamp with time zone, "provider" "text", "role" "text", "credits" integer, "free_credits" integer, "paid_until" timestamp with time zone, "generation_count" integer, "last_generation_at" timestamp with time zone, "banned_at" timestamp with time zone, "phone" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $_$
  select o.id, o.email, o.created_at, o.provider, o.role, o.credits, o.free_credits, o.paid_until,
         o.generation_count, o.last_generation_at, o.banned_at, o.phone
    from admin.users_overview o
   -- The query is a literal substring: % and _ typed by the admin match themselves.
   where length(btrim(coalesce(p_query, ''))) > 0
     and (o.email ilike '%' || replace(replace(replace(btrim(p_query), '\', '\\'), '%', '\%'), '_', '\_') || '%'
          or (btrim(p_query) ~ '^\+?[0-9][0-9 -]{2,}$'
              and length(regexp_replace(p_query, '[^0-9]', '', 'g')) >= 4
              and o.phone like '%' || regexp_replace(p_query, '[^0-9]', '', 'g') || '%'))
   order by o.created_at desc, o.id desc
   limit 50
$_$;


ALTER FUNCTION "public"."admin_search_users"("p_query" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_feature_access"("p_key" "text", "p_min_tier" "text", "p_open_to_all_at" timestamp with time zone, "p_actor" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if p_actor is null then
    raise exception 'INVALID_INPUT' using detail = 'actor is required';
  end if;
  if p_min_tier is not null and p_min_tier not in ('pro', 'max') then
    raise exception 'INVALID_INPUT' using detail = 'min_tier must be pro or max';
  end if;

  insert into public.feature_access (key, min_tier, open_to_all_at, updated_at, updated_by)
  values (p_key, p_min_tier, p_open_to_all_at, now(), p_actor)
  on conflict (key) do update
    set min_tier = excluded.min_tier,
        open_to_all_at = excluded.open_to_all_at,
        updated_at = excluded.updated_at,
        updated_by = excluded.updated_by;
end;
$$;


ALTER FUNCTION "public"."admin_set_feature_access"("p_key" "text", "p_min_tier" "text", "p_open_to_all_at" timestamp with time zone, "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_featured_templates"("p_ids" "text"[]) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_ids text[] := coalesce(p_ids, '{}');
begin
  if cardinality(v_ids) > 12 then
    raise exception 'at most 12 featured templates' using errcode = '22023';
  end if;
  if cardinality(v_ids) <> (select count(distinct id) from unnest(v_ids) as u(id)) then
    raise exception 'featured templates must not repeat' using errcode = '22023';
  end if;
  if exists (
    select 1 from unnest(v_ids) as u(id)
    where not exists (
      select 1 from public.templates t where t.id = u.id and t.is_active and 'web' = any (t.visible_in)
    )
  ) then
    raise exception 'only published web templates can be featured' using errcode = '22023';
  end if;

  update public.templates set featured_rank = null where featured_rank is not null;
  update public.templates t
  set featured_rank = o.position
  from unnest(v_ids) with ordinality as o(id, position)
  where t.id = o.id;
end;
$$;


ALTER FUNCTION "public"."admin_set_featured_templates"("p_ids" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_openai_admin_key"("p_key" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_name constant text := 'shotviva.openai_admin_key';
  v_secret uuid;
begin
  -- Same shape rule as provider keys: printable ASCII without whitespace, 16-1024 characters.
  if p_key is not null and (char_length(p_key) not between 16 and 1024 or p_key !~ '^[!-~]+$') then
    raise exception 'PROVIDER_KEY_INVALID' using errcode = '23514';
  end if;

  if p_key is null then
    delete from vault.secrets where name in (v_name, 'shotviva.openai_costs_project');
    return;
  end if;

  select id into v_secret from vault.secrets where name = v_name;
  if v_secret is null then
    perform vault.create_secret(p_key, v_name, 'Shotviva OpenAI Admin key (cost reconciliation)');
  else
    perform vault.update_secret(v_secret, p_key);
  end if;
end;
$_$;


ALTER FUNCTION "public"."admin_set_openai_admin_key"("p_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_openai_costs_project"("p_project_id" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_name constant text := 'shotviva.openai_costs_project';
  v_secret uuid;
begin
  if p_project_id is not null and p_project_id !~ '^proj_[A-Za-z0-9]{1,64}$' then
    raise exception 'INVALID_INPUT' using errcode = '23514', detail = 'project id must look like proj_…';
  end if;

  select id into v_secret from vault.secrets where name = v_name;
  if p_project_id is null then
    delete from vault.secrets where name = v_name;
  elsif v_secret is null then
    perform vault.create_secret(p_project_id, v_name, 'Shotviva OpenAI project id for cost reconciliation');
  else
    perform vault.update_secret(v_secret, p_project_id);
  end if;
end;
$_$;


ALTER FUNCTION "public"."admin_set_openai_costs_project"("p_project_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_provider_key"("p_id" "uuid", "p_key" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_secret uuid;
  v_name text := 'shotviva.provider.' || p_id::text;
begin
  -- Printable ASCII without whitespace, 16-1024 characters: every supported provider key fits.
  if p_key is not null and (char_length(p_key) not between 16 and 1024 or p_key !~ '^[!-~]+$') then
    raise exception 'PROVIDER_KEY_INVALID' using errcode = '23514';
  end if;

  select vault_secret_id into v_secret from public.ai_providers where id = p_id for update;
  if not found then
    raise exception 'PROVIDER_NOT_FOUND';
  end if;

  if p_key is null then
    delete from vault.secrets where id = v_secret or name = v_name;
    update public.ai_providers set vault_secret_id = null, api_key_last4 = null where id = p_id;
    return;
  end if;

  if v_secret is not null and exists (select 1 from vault.secrets where id = v_secret) then
    perform vault.update_secret(v_secret, p_key);
  else
    -- A leftover secret under this name is replaced, never reused blindly.
    delete from vault.secrets where name = v_name;
    v_secret := vault.create_secret(p_key, v_name, 'Shotviva image provider API key');
  end if;

  update public.ai_providers set vault_secret_id = v_secret, api_key_last4 = right(p_key, 4) where id = p_id;
end;
$_$;


ALTER FUNCTION "public"."admin_set_provider_key"("p_id" "uuid", "p_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_system_setting"("p_key" "text", "p_value" "jsonb", "p_actor" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if p_actor is null then
    raise exception 'INVALID_INPUT' using detail = 'actor is required';
  end if;
  if not exists (select 1 from public.profiles p where p.id = p_actor and p.role = 'admin') then
    raise exception 'NOT_ADMIN';
  end if;

  case p_key
    when 'wishlist_enabled' then
      if p_value is null or jsonb_typeof(p_value) <> 'boolean' then
        raise exception 'INVALID_INPUT' using detail = 'wishlist_enabled must be a boolean';
      end if;
    else
      raise exception 'INVALID_INPUT' using detail = 'unknown setting';
  end case;

  insert into public.system_settings (key, value, updated_at, updated_by)
  values (p_key, p_value, now(), p_actor)
  on conflict (key) do update
    set value = excluded.value,
        updated_at = excluded.updated_at,
        updated_by = excluded.updated_by;
end;
$$;


ALTER FUNCTION "public"."admin_set_system_setting"("p_key" "text", "p_value" "jsonb", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_template_order"("p_group" "text", "p_ids" "text"[], "p_actor" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_ids text[] := coalesce(p_ids, '{}');
  v_members text[];
begin
  if p_actor is null then
    raise exception 'INVALID_INPUT' using detail = 'actor is required';
  end if;
  if not exists (select 1 from public.profiles p where p.id = p_actor and p.role = 'admin') then
    raise exception 'NOT_ADMIN';
  end if;
  if p_group is null or p_group not in ('catalogue', 'featured') then
    raise exception 'INVALID_INPUT' using detail = 'group must be catalogue or featured';
  end if;
  if cardinality(v_ids) <> (select count(distinct id) from unnest(v_ids) as u(id)) then
    raise exception 'INVALID_INPUT' using detail = 'ids must not repeat';
  end if;

  -- Holds off other template writes for these few milliseconds, so the membership checked
  -- below is still the membership when the new order is written. Reads are not blocked.
  lock table public.templates in share row exclusive mode;

  select coalesce(array_agg(t.id), '{}') into v_members
  from public.templates t
  where case p_group
    when 'catalogue' then t.id <> 'edit'
    else t.featured_rank is not null
  end;

  if cardinality(v_members) <> cardinality(v_ids) or not (v_members @> v_ids) then
    raise exception 'ORDER_MISMATCH'
      using detail = format('%s ids given, the %s group has %s', cardinality(v_ids), p_group, cardinality(v_members));
  end if;

  if p_group = 'catalogue' then
    update public.templates t
    set sort_order = o.position * 10
    from unnest(v_ids) with ordinality as o(id, position)
    where t.id = o.id and t.sort_order is distinct from o.position * 10;
  else
    -- Cleared first so the one-per-position index never sees two rows on one rank mid-way.
    update public.templates set featured_rank = null where featured_rank is not null;
    update public.templates t
    set featured_rank = o.position
    from unnest(v_ids) with ordinality as o(id, position)
    where t.id = o.id;
  end if;
end;
$$;


ALTER FUNCTION "public"."admin_set_template_order"("p_group" "text", "p_ids" "text"[], "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_signup_ip_clusters"("p_days" integer) RETURNS TABLE("signup_ip" "inet", "accounts" integer, "last_signup_at" timestamp with time zone, "members" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_days is null or p_days not in (1, 7) then
    raise exception 'INVALID_INPUT' using detail = 'p_days must be 1 or 7';
  end if;

  return query
  with recent as (
    select p.id, p.signup_ip, p.created_at, p.free_credits, p.banned_at
      from public.profiles p
     where p.created_at >= now() - make_interval(days => p_days)
       and p.signup_ip is not null
  ), clusters as (
    select r.signup_ip, count(*)::integer as accounts, max(r.created_at) as last_signup_at
      from recent r
     group by r.signup_ip
    having count(*) >= 3
     order by count(*) desc, max(r.created_at) desc
     limit 50
  )
  select c.signup_ip, c.accounts, c.last_signup_at,
         (select jsonb_agg(jsonb_build_object(
                    'id', r.id,
                    'email', u.email,
                    'phone', nullif(u.phone, ''),
                    'created_at', r.created_at,
                    'free_credits', r.free_credits,
                    'free_used', coalesce(used.credits, 0),
                    'banned_at', r.banned_at)
                  order by r.created_at desc)
            from recent r
            left join auth.users u on u.id = r.id
            left join lateral (
              select -sum(l.delta)::integer as credits
                from public.credit_ledger l
               where l.user_id = r.id and l.pool = 'free' and l.kind in ('reserve', 'refund')
            ) used on true
           where r.signup_ip = c.signup_ip)
    from clusters c
   order by c.accounts desc, c.last_signup_at desc;
end;
$$;


ALTER FUNCTION "public"."admin_signup_ip_clusters"("p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_todo_counts"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'stuck_jobs', (
      select count(*) from public.generation_jobs
       where status = 'running' and created_at < now() - interval '10 minutes'),
    'jobs_1h', (
      select jsonb_build_object('total', count(*), 'failed', count(*) filter (where status = 'failed'))
        from public.generation_jobs where created_at >= now() - interval '1 hour'),
    'jobs_24h', (
      select jsonb_build_object('total', count(*), 'failed', count(*) filter (where status = 'failed'))
        from public.generation_jobs where created_at >= now() - interval '24 hours'),
    'pending_requests', (
      select count(*) from public.template_requests where status = 'pending'),
    'payment_issues', (
      select count(*) from public.payments
       where status <> 'paid' and created_at >= now() - interval '60 days'),
    'last_purchase_at', (
      select created_at from public.credit_ledger
       where kind = 'purchase' order by created_at desc, id desc limit 1),
    'provider', (
      select jsonb_build_object('label', label, 'model', model)
        from public.ai_providers where module = 'image' and is_active),
    'open_tickets', (
      select count(*) from public.support_tickets where status = 'open'),
    'overdue_tickets', (
      select count(*) from public.support_tickets t
       where t.status = 'open'
         and coalesce(
               (select max(m.created_at) from public.support_ticket_messages m
                 where m.ticket_id = t.id and m.author = 'user'),
               t.created_at)
             + make_interval(hours => public.support_reply_hours(public.current_tier(t.user_id))) < now())
  )
$$;


ALTER FUNCTION "public"."admin_todo_counts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_unban_user"("p_user_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_reason is null or length(btrim(p_reason)) = 0 then
    raise exception 'INVALID_INPUT' using detail = 'reason is required';
  end if;

  update public.profiles set banned_at = null where id = p_user_id;
  if not found then
    raise exception 'PROFILE_NOT_FOUND';
  end if;

  insert into public.admin_audit_log (action, user_id, reason) values ('unban_user', p_user_id, p_reason);
end;
$$;


ALTER FUNCTION "public"."admin_unban_user"("p_user_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_upsert_template"("p_template" "jsonb", "p_prompt" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_id text := p_template ->> 'id';
begin
  insert into public.templates as t (
    id, module, name, category, category_key, cover_before_url, cover_after_url,
    fields, quality, credits_cost, sort_order, is_active, visible_in, translations, description, featured_rank
  ) values (
    v_id,
    coalesce(p_template ->> 'module', 'image'),
    p_template ->> 'name',
    -- New code sends the key; old code and the prompt import send a name. The 0581 trigger
    -- fills whichever is missing.
    p_template ->> 'category',
    nullif(p_template ->> 'category_key', ''),
    nullif(p_template ->> 'cover_before_url', ''),
    nullif(p_template ->> 'cover_after_url', ''),
    coalesce(p_template -> 'fields', '{}'::jsonb),
    coalesce(p_template ->> 'quality', 'high'),
    -- Required: a template without its three prices must not save at some default.
    p_template -> 'credits_cost',
    -- New templates go to the end unless a position is given.
    coalesce(
      (p_template ->> 'sort_order')::integer,
      (select coalesce(max(sort_order), 0) + 10 from public.templates)
    ),
    coalesce((p_template ->> 'is_active')::boolean, false),
    array(select jsonb_array_elements_text(coalesce(p_template -> 'visible_in', '["web"]'::jsonb))),
    coalesce(p_template -> 'translations', '{}'::jsonb),
    nullif(btrim(p_template ->> 'description'), ''),
    (p_template ->> 'featured_rank')::smallint
  )
  on conflict (id) do update set
    module = excluded.module,
    name = excluded.name,
    category = excluded.category,
    -- After the BEFORE INSERT trigger, so always set (EXCLUDED carries the trigger's values).
    category_key = excluded.category_key,
    -- Only when the payload carries them: the editor leaves covers to the upload.
    cover_before_url = case when p_template ? 'cover_before_url' then excluded.cover_before_url else t.cover_before_url end,
    cover_after_url = case when p_template ? 'cover_after_url' then excluded.cover_after_url else t.cover_after_url end,
    fields = excluded.fields,
    quality = excluded.quality,
    credits_cost = excluded.credits_cost,
    sort_order = coalesce((p_template ->> 'sort_order')::integer, t.sort_order),
    is_active = coalesce((p_template ->> 'is_active')::boolean, t.is_active),
    visible_in = excluded.visible_in,
    -- The editor always sends the whole object; the prompt import script does not, and keeps it.
    translations = case when p_template ? 'translations' then excluded.translations else t.translations end,
    description = case when p_template ? 'description' then excluded.description else t.description end,
    featured_rank = case
      when p_template ? 'featured_rank' then excluded.featured_rank
      when coalesce((p_template ->> 'is_active')::boolean, t.is_active) and 'web' = any (excluded.visible_in) then t.featured_rank
      else null
    end;

  if p_prompt is not null then
    insert into public.template_prompts (template_id, body, model_params)
    values (v_id, p_prompt ->> 'body', coalesce(p_prompt -> 'model_params', '{}'::jsonb))
    on conflict (template_id) do update set
      body = excluded.body,
      model_params = excluded.model_params;
  end if;
end;
$$;


ALTER FUNCTION "public"."admin_upsert_template"("p_template" "jsonb", "p_prompt" "jsonb") OWNER TO "postgres";


