COMMENT ON COLUMN "public"."generation_jobs"."deleted_at" IS 'When the owner deleted this work (T41). Set only by delete_own_job; user-facing reads skip it.';



CREATE OR REPLACE FUNCTION "public"."confirm_job"("p_job_id" "uuid", "p_output_key" "text", "p_provider_usage" "jsonb" DEFAULT NULL::"jsonb", "p_cost_usd" numeric DEFAULT NULL::numeric, "p_kept_inputs" "text"[] DEFAULT NULL::"text"[]) RETURNS "public"."generation_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_job public.generation_jobs;
  v_prefix text;
  v_kept text[];
begin
  select * into v_job from public.generation_jobs where id = p_job_id for update;
  if not found then
    raise exception 'JOB_NOT_FOUND';
  end if;
  -- A repeat keeps the first settlement, usage, cost and kept inputs included.
  if v_job.status = 'succeeded' then
    return v_job;
  end if;
  if v_job.status = 'failed' then
    raise exception 'JOB_ALREADY_SETTLED';
  end if;
  if p_output_key is null or length(p_output_key) = 0 then
    raise exception 'INVALID_INPUT' using detail = 'output_key is required';
  end if;

  v_prefix := 'outputs/' || v_job.user_id::text || '/' || v_job.id::text || '-in-';
  select array_agg(k order by n) into v_kept
    from unnest(coalesce(p_kept_inputs, '{}'::text[])) with ordinality as t(k, n)
   where n <= 30 and k is not null and left(k, length(v_prefix)) = v_prefix and k not like '%/../%';

  update public.generation_jobs
     set status = 'succeeded', output_key = p_output_key, finished_at = now(),
         provider_usage = p_provider_usage, cost_usd = p_cost_usd,
         inputs = case when v_kept is null then inputs else inputs || jsonb_build_object('kept_inputs', to_jsonb(v_kept)) end
   where id = p_job_id
  returning * into v_job;
  return v_job;
end;
$$;


ALTER FUNCTION "public"."confirm_job"("p_job_id" "uuid", "p_output_key" "text", "p_provider_usage" "jsonb", "p_cost_usd" numeric, "p_kept_inputs" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_support_ticket"("p_user_id" "uuid", "p_type" "text", "p_body" "text", "p_payment_id" bigint, "p_job_id" "uuid", "p_ticket_id" "uuid" DEFAULT NULL::"uuid", "p_images" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "public"."support_tickets"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_ticket public.support_tickets;
  v_message_id uuid;
begin
  perform 1 from public.profiles where id = p_user_id for update;
  if not found then
    raise exception 'PROFILE_NOT_FOUND';
  end if;

  if p_type is null or p_type not in ('feedback', 'image_issue', 'billing', 'refund', 'account', 'other') then
    raise exception 'INVALID_INPUT' using detail = 'unknown ticket type';
  end if;
  if p_body is null or char_length(btrim(p_body)) not between 1 and 2000 then
    raise exception 'INVALID_INPUT' using detail = 'body must be 1 to 2000 characters';
  end if;
  if p_type = 'refund' and p_payment_id is null then
    raise exception 'INVALID_INPUT' using detail = 'a refund request needs a payment';
  end if;
  if p_payment_id is not null and p_type not in ('billing', 'refund') then
    raise exception 'INVALID_INPUT' using detail = 'only billing and refund tickets take a payment';
  end if;
  if p_job_id is not null and p_type <> 'image_issue' then
    raise exception 'INVALID_INPUT' using detail = 'only image issues take a work';
  end if;

  -- Someone else's id reads the same as a missing one, so nothing leaks about other accounts.
  if p_payment_id is not null and not exists (
    select 1 from public.payments p where p.id = p_payment_id and p.user_id = p_user_id
  ) then
    raise exception 'PAYMENT_NOT_FOUND';
  end if;
  if p_job_id is not null and not exists (
    select 1 from public.generation_jobs j where j.id = p_job_id and j.user_id = p_user_id
  ) then
    raise exception 'JOB_NOT_FOUND';
  end if;

  if (select count(*) from public.support_tickets t
       where t.user_id = p_user_id and t.created_at > now() - interval '24 hours') >= 5 then
    raise exception 'RATE_LIMITED';
  end if;

  insert into public.support_tickets (id, user_id, type, payment_id, job_id)
  values (coalesce(p_ticket_id, gen_random_uuid()), p_user_id, p_type, p_payment_id, p_job_id)
  returning * into v_ticket;

  insert into public.support_ticket_messages (ticket_id, author, body)
  values (v_ticket.id, 'user', btrim(p_body))
  returning id into v_message_id;

  perform public.attach_ticket_images(v_ticket.id, p_user_id, v_message_id, p_images);
  return v_ticket;
end;
$$;


ALTER FUNCTION "public"."create_support_ticket"("p_user_id" "uuid", "p_type" "text", "p_body" "text", "p_payment_id" bigint, "p_job_id" "uuid", "p_ticket_id" "uuid", "p_images" "jsonb") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."template_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "description" "text" NOT NULL,
    "image_keys" "text"[] NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "template_id" "text",
    "votes_count" integer DEFAULT 0 NOT NULL,
    "author_label" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "reviewed_at" timestamp with time zone,
    CONSTRAINT "template_requests_author_label_check" CHECK (("author_label" ~ '^.\*\*\*$'::"text")),
    CONSTRAINT "template_requests_description_check" CHECK ((("char_length"("btrim"("description")) >= 1) AND ("char_length"("btrim"("description")) <= 300))),
    CONSTRAINT "template_requests_images" CHECK (
CASE
    WHEN ("status" = 'rejected'::"text") THEN ("cardinality"("image_keys") = 0)
    ELSE (("cardinality"("image_keys") >= 1) AND ("cardinality"("image_keys") <= 3))
END),
    CONSTRAINT "template_requests_reviewed" CHECK ((("status" = 'pending'::"text") = ("reviewed_at" IS NULL))),
    CONSTRAINT "template_requests_shipped_template" CHECK ((("status" = 'shipped'::"text") = ("template_id" IS NOT NULL))),
    CONSTRAINT "template_requests_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'live'::"text", 'shipped'::"text", 'rejected'::"text"]))),
    CONSTRAINT "template_requests_votes_count_check" CHECK (("votes_count" >= 0))
);


ALTER TABLE "public"."template_requests" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_template_request"("p_user_id" "uuid", "p_description" "text", "p_image_keys" "text"[]) RETURNS "public"."template_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_request public.template_requests;
  v_name text;
  v_key text;
begin
  perform 1 from public.profiles where id = p_user_id for update;
  if not found then
    raise exception 'PROFILE_NOT_FOUND';
  end if;

  if not public.wishlist_eligible(p_user_id) then
    raise exception 'WISHLIST_NOT_ELIGIBLE';
  end if;

  if cardinality(coalesce(p_image_keys, '{}')) not between 1 and 3 then
    raise exception 'INVALID_INPUT' using detail = '1 to 3 reference images';
  end if;
  foreach v_key in array p_image_keys loop
    if v_key is null or v_key !~ ('^requests/' || p_user_id::text || '/[0-9a-f-]{36}\.jpg$') then
      raise exception 'INVALID_INPUT' using detail = 'image key outside the author prefix';
    end if;
  end loop;

  if (select count(*) from public.template_requests r
       where r.user_id = p_user_id and r.created_at > now() - interval '24 hours') >= 5 then
    raise exception 'RATE_LIMITED';
  end if;

  -- Display name first (Google sign-ups), else the email; only its first letter leaves here.
  select coalesce(nullif(btrim(u.raw_user_meta_data ->> 'full_name'), ''),
                  nullif(btrim(u.raw_user_meta_data ->> 'name'), ''),
                  u.email,
                  '?')
    into v_name
    from auth.users u
   where u.id = p_user_id;

  insert into public.template_requests (user_id, description, image_keys, author_label)
  values (p_user_id, btrim(p_description), p_image_keys, upper(left(coalesce(v_name, '?'), 1)) || '***')
  returning * into v_request;
  return v_request;
end;
$_$;


ALTER FUNCTION "public"."create_template_request"("p_user_id" "uuid", "p_description" "text", "p_image_keys" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."current_tier"("p_user_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_paid_until timestamptz;
  v_product_id text;
begin
  select paid_until into v_paid_until from public.profiles where id = p_user_id;
  if v_paid_until is null or v_paid_until <= now() then
    return null;
  end if;

  select l.product_id into v_product_id
    from public.credit_ledger l
   where l.user_id = p_user_id
     and l.pool = 'paid'
     and l.delta > 0
     and l.product_id is not null
     and l.product_id not like 'pack_%'
     and not exists (
       select 1 from public.payments p
        where p.user_id = p_user_id
          and p.status in ('refunded', 'partially_refunded')
          and l.idempotency_key in ('purchase:' || p.stripe_session_id, 'renewal:' || p.stripe_invoice_id, 'purchase:' || p.waffo_payment_id)
     )
   order by l.created_at desc, l.id desc
   limit 1;

  if v_product_id is null then
    return null;
  end if;
  return split_part(v_product_id, '_', 1);
end;
$$;


ALTER FUNCTION "public"."current_tier"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_own_job"("p_job_id" "uuid", "p_user_id" "uuid") RETURNS "public"."generation_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_job public.generation_jobs;
begin
  select * into v_job from public.generation_jobs
   where id = p_job_id and user_id = p_user_id
     for update;
  if not found then
    raise exception 'JOB_NOT_FOUND';
  end if;
  if v_job.deleted_at is not null then
    return v_job;
  end if;
  if v_job.status = 'running' then
    raise exception 'JOB_RUNNING';
  end if;

  update public.generation_jobs
     set deleted_at = now(), inputs = inputs - 'note' - 'copy' - 'instruction'
   where id = p_job_id
  returning * into v_job;
  return v_job;
end;
$$;


ALTER FUNCTION "public"."delete_own_job"("p_job_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


