ALTER FUNCTION "public"."template_categories_sync_name"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."template_category_for"("p_value" "text") RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_value text := btrim(coalesce(p_value, ''));
  v_key text;
  v_base text;
  v_name_en text;
  v_name_zh text;
  v_n integer;
begin
  if v_value = '' then
    return null;
  end if;
  select c.key into v_key
  from public.template_categories c
  where c.key = v_value or lower(c.name_en) = lower(v_value) or c.name_zh = v_value
  order by (c.key = v_value) desc, c.sort_order
  limit 1;
  if v_key is not null then
    return v_key;
  end if;

  v_base := rtrim(left(btrim(regexp_replace(lower(v_value), '[^a-z0-9]+', '-', 'g'), '-'), 36), '-');
  if v_base = '' then
    v_base := 'category';
  end if;
  v_key := v_base;
  v_n := 1;
  while exists (select 1 from public.template_categories c where c.key = v_key) loop
    v_n := v_n + 1;
    v_key := v_base || '-' || v_n;
  end loop;

  v_name_en := btrim(left(v_value, 32));
  v_n := 1;
  while exists (select 1 from public.template_categories c where lower(c.name_en) = lower(v_name_en)) loop
    v_n := v_n + 1;
    v_name_en := btrim(left(v_value, 32 - length(' ' || v_n))) || ' ' || v_n;
  end loop;
  v_name_zh := btrim(left(v_value, 12));
  v_n := 1;
  while exists (select 1 from public.template_categories c where c.name_zh = v_name_zh) loop
    v_n := v_n + 1;
    v_name_zh := btrim(left(v_value, 12 - length(' ' || v_n))) || ' ' || v_n;
  end loop;

  insert into public.template_categories (key, name_en, name_zh, card_style, sort_order)
  values (
    v_key, v_name_en, v_name_zh, 'pair',
    (select coalesce(max(c.sort_order), 0) + 10 from public.template_categories c where not c.is_system)
  );
  return v_key;
end;
$$;


ALTER FUNCTION "public"."template_category_for"("p_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."template_favorites_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform 1 from public.profiles where id = new.user_id for update;
  if not found then
    raise exception 'PROFILE_NOT_FOUND';
  end if;

  if exists (
    select 1 from public.template_favorites f
     where f.user_id = new.user_id and f.template_id = new.template_id
  ) then
    return new;
  end if;

  if not exists (
    select 1 from public.templates t
     where t.id = new.template_id and t.is_active and 'web' = any (t.visible_in)
  ) then
    raise exception 'TEMPLATE_NOT_FOUND';
  end if;

  if (select count(*) from public.template_favorites f where f.user_id = new.user_id) >= 200 then
    raise exception 'FAVORITES_LIMIT';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."template_favorites_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."template_request_votes_count"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    update public.template_requests set votes_count = votes_count + new.weight where id = new.request_id;
  else
    update public.template_requests set votes_count = votes_count - old.weight where id = old.request_id;
  end if;
  return null;
end;
$$;


ALTER FUNCTION "public"."template_request_votes_count"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."templates_sync_category"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if new.category_key is not null and (tg_op = 'INSERT' or new.category_key is distinct from old.category_key) then
    -- The key was written: the name follows it below.
    null;
  elsif tg_op = 'INSERT' or new.category is distinct from old.category then
    -- Only the name was written. A rename of the template's own category keeps its key.
    if tg_op = 'INSERT' or not exists (
      select 1 from public.template_categories c
      where c.key = new.category_key
        and (c.key = btrim(new.category) or lower(c.name_en) = lower(btrim(new.category)) or c.name_zh = btrim(new.category))
    ) then
      new.category_key := public.template_category_for(new.category);
    end if;
  end if;
  -- An unknown key keeps a non-null name, so the foreign key (not NOT NULL) is what refuses it.
  new.category := coalesce((select c.name_en from public.template_categories c where c.key = new.category_key), new.category, new.category_key);
  return new;
end;
$$;


ALTER FUNCTION "public"."templates_sync_category"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."toggle_template_request_vote"("p_request_id" "uuid", "p_user_id" "uuid") RETURNS TABLE("voted" boolean, "votes_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_status text;
  v_weight smallint;
begin
  if not public.wishlist_eligible(p_user_id) then
    raise exception 'WISHLIST_NOT_ELIGIBLE';
  end if;

  select r.status into v_status from public.template_requests r where r.id = p_request_id for update;
  if not found then
    raise exception 'REQUEST_NOT_FOUND';
  end if;
  if v_status <> 'live' then
    raise exception 'REQUEST_NOT_LIVE';
  end if;

  delete from public.template_request_votes v
   where v.request_id = p_request_id and v.user_id = p_user_id;
  if found then
    voted := false;
  else
    v_weight := case when public.current_tier(p_user_id) = 'max' then 3 else 1 end;
    insert into public.template_request_votes (request_id, user_id, weight)
    values (p_request_id, p_user_id, v_weight);
    voted := true;
  end if;

  select r.votes_count into votes_count from public.template_requests r where r.id = p_request_id;
  return next;
end;
$$;


ALTER FUNCTION "public"."toggle_template_request_vote"("p_request_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wishlist_eligible"("p_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
           select 1 from public.generation_jobs j
            where j.user_id = p_user_id and j.status = 'succeeded'
         )
     and exists (
           select 1 from public.profiles p
            where p.id = p_user_id and p.banned_at is null
         );
$$;


ALTER FUNCTION "public"."wishlist_eligible"("p_user_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."profiles" (
    "id" "uuid" NOT NULL,
    "role" "text" DEFAULT 'user'::"text" NOT NULL,
    "credits" integer DEFAULT 0 NOT NULL,
    "paid_until" timestamp with time zone,
    "signup_ip" "inet",
    "banned_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "free_credits" integer DEFAULT 0 NOT NULL,
    CONSTRAINT "profiles_credits_check" CHECK (("credits" >= 0)),
    CONSTRAINT "profiles_free_credits_check" CHECK (("free_credits" >= 0)),
    CONSTRAINT "profiles_role_check" CHECK (("role" = ANY (ARRAY['user'::"text", 'admin'::"text"])))
);


